mapper.select:
select message_id, session_id, user_id, role, content, content_type, refs_json, task_id, result_json, tokens, status, create_time
  from learning_agent_message
 where session_id = #{sessionId} and user_id = #{userId} and status = '0'

   and message_id < #{beforeMessageId}

 order by message_id desc
 limit #{pageSize}
